28	        context_w = context_wc;
29	      } else {
30	        if (Object.prototype.hasOwnProperty.call(context_dictionaryToCreate, context_w)) {
31	          if (context_w.charCodeAt(0) < 256) {
32	            for (i = 0; i < context_numBits; i++) {
33	              context_data_val = context_data_val << 1;
34	              if (context_data_position == bitsPerChar - 1) {
35	                context_data_position = 0;
36	                context_data.push(getCharFromInt(context_data_val));
37	                context_data_val = 0;
38	              } else {
39	                context_data_position++;
40	              }
41	            }
