96	            }
97	            value = value >> 1;
98	          }
99	        }
100	        context_enlargeIn--;
101	        if (context_enlargeIn == 0) {
102	          context_enlargeIn = Math.pow(2, context_numBits);
103	          context_numBits++;
104	        }
105	        context_dictionary[context_wc] = context_dictSize++;
106	        context_w = String(context_c);
107	      }
108	    }
109	    if (context_w !== "") {
110	      if (Object.prototype.hasOwnProperty.call(context_dictionaryToCreate, context_w)) {
111	        if (context_w.charCodeAt(0) < 256) {
112	          for (i = 0; i < context_numBits; i++) {
113	            context_data_val = context_data_val << 1;
114	            if (context_data_position == bitsPerChar - 1) {
115	              context_data_position = 0;
116	              context_data.push(getCharFromInt(context_data_val));
117	              context_data_val = 0;
118	            } else {
