    if r.returncode == 0:
        gate_results = json.loads(r.stdout.strip())
        faults["below_threshold"] = (
            gate_results.get("below_threshold") is False
            and gate_results.get("at_threshold") is True
            and gate_results.get("above_threshold") is True
        )
